select 'pm-mudra-yojana', c.id, 'scheme', 'PM Mudra Yojana', 'पीएम मुद्रा योजना', 'Collateral-free loans for micro and small non-farm businesses through banks and lenders.', 'बैंकों के माध्यम से सूक्ष्म और लघु व्यवसायों के लिए बिना गारंटी लोन।', 'Pradhan Mantri MUDRA Yojana enables loans to micro enterprises in manufacturing, trading and services through member lending institutions, across loan categories defined by the scheme.', array['Loan categories for different stages of business (Shishu, Kishore, Tarun and others as notified)','No collateral requirement as per scheme rules']::text[], array['Non-farm income-generating micro enterprise','Lender''s credit assessment applies']::text[], array['Identity and address proof','Business proof / plan','Bank statements','Quotation for machinery (if applicable)']::text[], array['Prepare a simple business plan and estimate the loan amount.','Apply at a bank/NBFC/MFI branch or on the official Jan Samarth / lender portal.','Submit KYC and business documents.','The lender evaluates and sanctions the loan at its discretion.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'MUDRA official website', 'https://www.mudra.org.in', 19900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', true, true, true, 9
