select 'pmegp-loan', c.id, 'scheme', 'PMEGP Loan', 'पीएमईजीपी लोन', 'Credit-linked subsidy programme for setting up new micro enterprises.', 'नए सूक्ष्म उद्यम शुरू करने के लिए क्रेडिट-लिंक्ड सब्सिडी कार्यक्रम।', 'The Prime Minister''s Employment Generation Programme, implemented by KVIC, offers margin-money subsidy on bank loans for new enterprises, as per programme rules.', array['Margin money subsidy on project cost (rate as per category and area)','Supports manufacturing and service units']::text[], array['Age and education criteria as per guidelines','New project only','Other conditions as notified']::text[], array['Aadhaar','Project report','Education certificate','Caste/category certificate (if applicable)','Rural area certificate (if applicable)']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'KVIC PMEGP e-Portal', 'https://www.kviconline.gov.in/pmegpeportal/', 29900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', true, false, true, 10
