select 'education-loan-guidance', c.id, 'guidance', 'Education Loan Guidance', 'शिक्षा लोन मार्गदर्शन', 'Understand education loan options, interest subsidy schemes and how to apply.', 'शिक्षा लोन विकल्प, ब्याज सब्सिडी योजनाएँ और आवेदन प्रक्रिया समझें।', 'Banks offer education loans for studies in India and abroad. Some government schemes provide interest subsidy for eligible students.', array['Compare loan options','Know which subsidy schemes may apply','Checklist of documents']::text[], array['Admission to a recognised course','Co-borrower requirements as per lender']::text[], array['Admission letter','Fee structure','Academic records','KYC of student and co-borrower','Income proof of co-borrower']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'Jan Samarth portal', 'https://www.jansamarth.in', 19900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', false, false, true, 11
