select 'agriculture-loan-schemes', c.id, 'guidance', 'Agriculture Loan Schemes & Kisan Credit Card', 'कृषि लोन योजनाएँ और किसान क्रेडिट कार्ड', 'Guidance on Kisan Credit Card and agriculture loan options from banks.', 'किसान क्रेडिट कार्ड और बैंकों की कृषि लोन योजनाओं पर मार्गदर्शन।', 'The Kisan Credit Card (KCC) scheme provides farmers with credit for cultivation and allied needs through banks. Interest subvention may apply as per current Government notifications.', array['Short-term crop credit','Possible interest subvention on timely repayment (as notified)']::text[], array['Farmers (owner cultivators, tenant farmers, etc. as per bank norms)','Allied activities as per scheme']::text[], array['Aadhaar','Land records','Crop details','Bank account','Passport-size photo']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'myScheme (Government of India)', 'https://www.myscheme.gov.in', 14900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', false, false, true, 12
