select 'business-loan-assistance', c.id, 'guidance', 'Business Loan Assistance', 'बिज़नेस लोन सहायता', 'Find the right government-backed or bank business loan and prepare your application.', 'सही सरकारी या बैंक बिज़नेस लोन चुनें और आवेदन तैयार करें।', 'We help you compare business loan routes — MUDRA, PMEGP, Stand-Up India, CGTMSE-backed loans and regular bank loans — and prepare documents.', array['Loan route recommendation','Document checklist','Project report guidance']::text[], array['Existing or proposed business','Lender eligibility applies']::text[], array['KYC','Business registration (Udyam/GST if available)','Bank statements','ITR (if available)']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'Jan Samarth portal', 'https://www.jansamarth.in', 29900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', true, false, true, 13
