select 'stand-up-india', c.id, 'scheme', 'Stand-Up India', 'स्टैंड-अप इंडिया', 'Bank loans for greenfield enterprises by SC/ST and women entrepreneurs.', 'एससी/एसटी और महिला उद्यमियों के नए उद्यमों के लिए बैंक लोन।', 'Stand-Up India facilitates bank loans for greenfield enterprises set up by eligible SC/ST and women entrepreneurs, within the range defined by the scheme.', array['Bank loan for a new enterprise','Handholding support via the portal']::text[], array['SC/ST or woman entrepreneur','Greenfield enterprise','Other conditions as per scheme']::text[], array['KYC','Caste certificate (if applicable)','Project report','Business address proof']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'Stand-Up Mitra portal', 'https://www.standupmitra.in', 29900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', false, false, true, 14
