select 'pm-svanidhi', c.id, 'scheme', 'PM SVANidhi (Street Vendor Loan)', 'पीएम स्वनिधि (रेहड़ी-पटरी लोन)', 'Working-capital loans for street vendors.', 'रेहड़ी-पटरी विक्रेताओं के लिए कार्यशील पूंजी लोन।', 'PM SVANidhi offers working-capital loans to eligible street vendors, with incentives for timely repayment and digital transactions as per scheme rules.', array['Collateral-free working-capital loan','Incentives as notified']::text[], array['Street vendor with certificate of vending / identity card or recommendation','Urban local body area']::text[], array['Aadhaar','Vending certificate or Letter of Recommendation','Bank account']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'PM SVANidhi portal', 'https://pmsvanidhi.mohua.gov.in', 9900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', false, false, true, 15
