select 'jan-dhan-account', c.id, 'service', 'Jan Dhan Bank Account', 'जन धन बैंक खाता', 'Basic savings bank account under PM Jan Dhan Yojana.', 'पीएम जन धन योजना के तहत बुनियादी बचत खाता।', 'PMJDY provides basic savings bank accounts with RuPay debit card and access to linked schemes.', array['Basic savings account','RuPay debit card','Access to DBT and insurance schemes']::text[], array['Indian resident','KYC documents']::text[], array['Aadhaar or other officially valid document','Photograph']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'PMJDY official website', 'https://pmjdy.gov.in', null, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', false, false, true, 16
