select 'national-scholarship-portal', c.id, 'scholarship', 'National Scholarship Portal (Central Scholarships)', 'राष्ट्रीय छात्रवृत्ति पोर्टल (केंद्रीय छात्रवृत्ति)', 'Apply for Central Government scholarships through NSP.', 'एनएसपी के माध्यम से केंद्र सरकार की छात्रवृत्तियों के लिए आवेदन।', 'The National Scholarship Portal hosts many Central and some State scholarships, including pre-matric, post-matric and merit-based schemes.', array['Single portal for multiple scholarships','Direct transfer to student bank account']::text[], array['Varies by scholarship — income, category, marks and course criteria']::text[], array['Aadhaar','Income certificate','Caste certificate (if applicable)','Previous marksheet','Fee receipt','Bank account']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Academic year application window","date":null,"note":"Announced each year on NSP."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'National Scholarship Portal', 'https://scholarships.gov.in', 9900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', true, true, true, 17
