select 'state-scholarships', c.id, 'scholarship', 'State Scholarships Guidance', 'राज्य छात्रवृत्ति मार्गदर्शन', 'Find and apply for scholarships run by your State Government.', 'अपनी राज्य सरकार की छात्रवृत्तियाँ खोजें और आवेदन करें।', 'Most States run their own scholarship portals. We help you identify the right portal and scheme for your State and course.', array['State-specific shortlist','Document checklist']::text[], array['Domicile of the State','Scheme-specific criteria']::text[], array['Domicile certificate','Income certificate','Marksheets','Bank account']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'National Scholarship Portal', 'https://scholarships.gov.in', 9900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', false, false, true, 18
