select 'school-scholarships', c.id, 'scholarship', 'School Scholarships (Class 1–12)', 'स्कूल छात्रवृत्ति (कक्षा 1–12)', 'Pre-matric, merit-cum-means and other school-level scholarships.', 'प्री-मैट्रिक, मेरिट-कम-मीन्स और अन्य स्कूल स्तर की छात्रवृत्तियाँ।', 'School students may be eligible for pre-matric scholarships and merit-based schemes such as NMMS, depending on category and income.', array['Financial support for school education']::text[], array['Enrolled school student','Category, income and marks criteria as per scheme']::text[], array['School ID / bonafide certificate','Income certificate','Marksheet','Bank account (student or guardian)']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'National Scholarship Portal', 'https://scholarships.gov.in', 9900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', false, false, true, 19
