select 'government-job-listings', c.id, 'job', 'Government Job Listings & Alerts', 'सरकारी नौकरी सूची और अलर्ट', 'Where to find genuine Central and State recruitment notifications.', 'केंद्र और राज्य भर्ती की असली अधिसूचनाएँ कहाँ देखें।', 'Official recruitment notifications are published by recruiting bodies and in Employment News. Sabkaam lists curated openings once verified by our editors.', array['Avoid fake job sites','Get help with eligibility and online forms']::text[], array['As per each notification']::text[], array['Educational certificates','Photo and signature (as per specifications)','Category certificate (if applicable)']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Dates","date":null,"note":"Each recruitment has its own dates — always check the official notification."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'Employment News', 'https://www.employmentnews.gov.in', 9900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', true, true, true, 22
