select 'apply-pan-card', c.id, 'service', 'Apply for PAN Card', 'पैन कार्ड के लिए आवेदन', 'Apply for a new PAN, including instant e-PAN using Aadhaar.', 'नया पैन, आधार से तुरंत ई-पैन सहित, के लिए आवेदन।', 'Permanent Account Number (PAN) is issued by the Income Tax Department. You can apply through the authorised PAN service portals or get an instant e-PAN using Aadhaar on the e-filing portal.', array['Required for tax filing, high-value transactions and opening many financial accounts']::text[], array['Individuals and entities as per Income Tax rules','Instant e-PAN requires valid Aadhaar with linked mobile']::text[], array['Proof of identity','Proof of address','Proof of date of birth','Photograph and signature (for physical applications)']::text[], array['Choose instant e-PAN (Aadhaar-based) or a regular application through an authorised PAN portal.','Fill Form 49A (Indian citizens) online.','Upload/submit documents and pay the official fee on the portal.','Track using the acknowledgement number.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'Income Tax Department e-Filing portal', 'https://www.incometax.gov.in', 9900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', true, true, true, 31
