select 'pan-card-correction', c.id, 'service', 'PAN Card Correction', 'पैन कार्ड सुधार', 'Correct name, date of birth, photo or other details on your PAN.', 'पैन पर नाम, जन्मतिथि, फोटो या अन्य विवरण में सुधार।', 'Changes or corrections to PAN data are made through the ''Changes or Correction in PAN Data'' application on authorised PAN service portals.', array['Updated PAN details matching your other documents']::text[], array['Existing PAN holder']::text[], array['Copy of PAN','Proof supporting the correction (e.g., ID showing correct name/DOB)']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'Income Tax Department e-Filing portal', 'https://www.incometax.gov.in', 9900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', true, false, true, 32
