select 'pan-card-status', c.id, 'guidance', 'PAN Card Status', 'पैन कार्ड स्टेटस', 'Track your PAN application using the acknowledgement number.', 'पावती संख्या से अपने पैन आवेदन की स्थिति देखें।', 'PAN application status can be checked on the portal where you applied, using your acknowledgement number.', array['Know where your application is','Find out if more documents are needed']::text[], array['Anyone who has applied for PAN']::text[], array['Acknowledgement / token number']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'Income Tax Department e-Filing portal', 'https://www.incometax.gov.in', 4900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', false, false, true, 33
