select 'pan-card-documents', c.id, 'guidance', 'PAN Card Documents Required', 'पैन कार्ड के लिए ज़रूरी दस्तावेज़', 'Which identity, address and date-of-birth proofs are accepted for PAN.', 'पैन के लिए कौन-से पहचान, पता और जन्मतिथि प्रमाण मान्य हैं।', 'A plain-language guide to the categories of documents accepted for PAN applications. The authoritative list is in the official form instructions.', array['Avoid rejection due to wrong documents']::text[], array['Anyone applying for PAN']::text[], array['Proof of identity','Proof of address','Proof of date of birth']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'Income Tax Department e-Filing portal', 'https://www.incometax.gov.in', null, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', false, false, true, 34
