select 'aadhaar-update', c.id, 'service', 'Aadhaar Update & Services', 'आधार अपडेट और सेवाएँ', 'Update address, download e-Aadhaar, and find enrolment centres.', 'पता अपडेट, ई-आधार डाउनलोड और नामांकन केंद्र खोजें।', 'Aadhaar is issued by UIDAI. Some updates (like address) can be done online on myAadhaar; biometric and some demographic updates need an Aadhaar Seva Kendra.', array['Keep your Aadhaar details current','Download e-Aadhaar']::text[], array['Aadhaar holder (updates)','Residents for new enrolment']::text[], array['Proof of identity / address as per UIDAI''s list','Registered mobile number for online services']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'UIDAI', 'https://uidai.gov.in', 4900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', true, true, true, 36
