select 'voter-id-card', c.id, 'service', 'Voter ID (EPIC) — New, Correction & Download', 'वोटर आईडी (EPIC) — नया, सुधार और डाउनलोड', 'Register as a voter, correct details or download e-EPIC.', 'मतदाता के रूप में पंजीकरण, सुधार या ई-EPIC डाउनलोड।', 'Voter registration and corrections are done through the Election Commission''s Voters'' Service Portal using the relevant forms.', array['Right to vote','Widely accepted identity document']::text[], array['Indian citizen aged 18 or above on the qualifying date','Ordinary resident of the constituency']::text[], array['Age proof','Address proof','Passport-size photograph']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'Voters'' Service Portal (ECI)', 'https://voters.eci.gov.in', 4900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', true, false, true, 37
