select 'income-caste-domicile-certificate', c.id, 'service', 'Income, Caste & Domicile Certificates', 'आय, जाति और निवास प्रमाणपत्र', 'Apply through your State''s e-District / service portal.', 'अपने राज्य के ई-डिस्ट्रिक्ट / सेवा पोर्टल से आवेदन करें।', 'These certificates are issued by State revenue authorities, usually through e-District or State service portals. Process and fees vary by State.', array['Needed for scholarships, reservations and many schemes']::text[], array['Resident of the State; criteria as per State rules']::text[], array['Aadhaar','Address proof','Income proof / affidavit','Family caste records (for caste certificate)']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'National Government Services Portal', 'https://services.india.gov.in', 9900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', true, false, true, 41
