select 'credit-score-basics', c.id, 'guidance', 'Credit Score & CIBIL Explained', 'क्रेडिट स्कोर और सिबिल समझें', 'What a credit score is, who calculates it and why lenders use it.', 'क्रेडिट स्कोर क्या है, कौन बनाता है और बैंक इसे क्यों देखते हैं।', 'Credit information companies such as TransUnion CIBIL, Experian, Equifax and CRIF High Mark prepare credit reports and scores from lender data. Lenders use them to assess credit risk.', array['Understand how scores work','Know what affects your score']::text[], array['Anyone']::text[], array[]::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'Reserve Bank of India', 'https://www.rbi.org.in', null, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', true, false, true, 43
