select 'free-credit-report', c.id, 'guidance', 'Get Your Free Credit Report', 'मुफ़्त क्रेडिट रिपोर्ट पाएँ', 'How to request your credit report from credit bureaus.', 'क्रेडिट ब्यूरो से अपनी क्रेडिट रिपोर्ट कैसे माँगें।', 'Individuals can obtain their credit report from credit information companies. RBI rules provide for a free full credit report periodically — check current RBI directions.', array['Spot errors early','Know your credit standing before applying for a loan']::text[], array['Anyone with a credit history']::text[], array['PAN','Identity details']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'TransUnion CIBIL', 'https://www.cibil.com', null, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', false, false, true, 44
