select 'credit-report-dispute', c.id, 'guidance', 'Credit Report Error / Dispute Guidance', 'क्रेडिट रिपोर्ट त्रुटि / विवाद मार्गदर्शन', 'How to raise a dispute with a credit bureau for incorrect entries.', 'गलत प्रविष्टियों के लिए क्रेडिट ब्यूरो में विवाद कैसे दर्ज करें।', 'If your credit report has incorrect information, you can raise a dispute with the credit information company. Escalation routes include the RBI Integrated Ombudsman Scheme.', array['Correct inaccurate records','Understand escalation options']::text[], array['Anyone with an error in their credit report']::text[], array['Credit report','Supporting proof (e.g., loan closure letter / NOC)']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'RBI Complaint Management System', 'https://cms.rbi.org.in', 19900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', false, false, true, 45
