select 'improve-credit-score', c.id, 'guidance', 'Credit Score Improvement Education', 'क्रेडिट स्कोर सुधार शिक्षा', 'Practical, honest habits that help a credit profile over time.', 'व्यावहारिक आदतें जो समय के साथ क्रेडिट प्रोफ़ाइल को बेहतर बनाती हैं।', 'There is no instant fix for a credit score. Timely repayments, sensible credit utilisation and fewer hard enquiries generally help over time. Beware of anyone promising guaranteed score increases.', array['Clear, unbiased education','Personalised habit plan (assistance)']::text[], array['Anyone']::text[], array['Recent credit report (for personalised guidance)']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'Reserve Bank of India', 'https://www.rbi.org.in', 14900, array['Review of your credit report with you','Explanation of each entry','Personalised habit plan','No guaranteed score outcome']::text[], 'demo', false, false, true, 46
