select 'ayushman-bharat-pmjay', c.id, 'scheme', 'Ayushman Bharat PM-JAY', 'आयुष्मान भारत पीएम-जय', 'Health cover for eligible families for secondary and tertiary hospitalisation.', 'पात्र परिवारों के लिए अस्पताल में भर्ती पर स्वास्थ्य कवर।', 'Pradhan Mantri Jan Arogya Yojana provides cashless health cover at empanelled hospitals to eligible beneficiaries, with cover limits and eligibility as notified by the National Health Authority.', array['Cashless treatment at empanelled hospitals','Cover as per current scheme limits']::text[], array['Families identified under scheme criteria','Additional categories as notified (check current notifications)']::text[], array['Aadhaar','Ration card / family ID','Mobile number']::text[], array['Check eligibility on the official beneficiary portal.','Complete e-KYC.','Download the Ayushman card.','Use the card at an empanelled hospital.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'National Health Authority — PM-JAY', 'https://pmjay.gov.in', 4900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', true, true, true, 47
