select 'abha-health-id', c.id, 'service', 'ABHA Health ID', 'आभा हेल्थ आईडी', 'Create your Ayushman Bharat Health Account for digital health records.', 'डिजिटल स्वास्थ्य रिकॉर्ड के लिए आयुष्मान भारत हेल्थ अकाउंट बनाएँ।', 'ABHA is a health ID under the Ayushman Bharat Digital Mission that helps link and share your health records with consent.', array['Consent-based sharing of health records']::text[], array['Anyone']::text[], array['Aadhaar or driving licence','Mobile number']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'ABDM', 'https://abha.abdm.gov.in', null, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', false, false, true, 48
