select 'pm-awas-yojana', c.id, 'scheme', 'PM Awas Yojana (Urban & Gramin)', 'पीएम आवास योजना (शहरी और ग्रामीण)', 'Housing assistance for eligible urban and rural households.', 'पात्र शहरी और ग्रामीण परिवारों के लिए आवास सहायता।', 'Pradhan Mantri Awas Yojana has Urban (PMAY-U) and Gramin (PMAY-G) components with different eligibility and processes. Current phases and components should be checked on the official portals.', array['Financial assistance for house construction / purchase as per component']::text[], array['Household income category and no pucca house criteria, as per component','Rural beneficiaries identified as per PMAY-G process']::text[], array['Aadhaar of family members','Income proof','Bank account','Land/property documents (where applicable)']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'PMAY-Urban portal', 'https://pmay-urban.gov.in', 14900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', true, true, true, 49
