select 'udyam-registration', c.id, 'service', 'Udyam (MSME) Registration', 'उद्यम (एमएसएमई) पंजीकरण', 'Free online MSME registration on the official Udyam portal.', 'आधिकारिक उद्यम पोर्टल पर निःशुल्क ऑनलाइन एमएसएमई पंजीकरण।', 'Udyam Registration is the official MSME registration. Registration on the official portal is free of charge. Our fee is only for optional guidance.', array['MSME recognition','Eligibility for MSME-linked schemes and benefits']::text[], array['Micro, small or medium enterprise as per investment and turnover limits']::text[], array['Aadhaar of proprietor/partner/director','PAN','GSTIN (where applicable)','Bank details']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'Udyam Registration portal', 'https://udyamregistration.gov.in', 14900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', true, true, true, 51
