select 'msme-services', c.id, 'guidance', 'MSME Schemes & Services', 'एमएसएमई योजनाएँ और सेवाएँ', 'Overview of credit guarantee, procurement and support schemes for MSMEs.', 'एमएसएमई के लिए क्रेडिट गारंटी, खरीद और सहायता योजनाओं का अवलोकन।', 'The Ministry of MSME runs schemes including credit guarantee (CGTMSE), public procurement support and cluster development. We help you shortlist relevant ones.', array['Scheme shortlist for your business']::text[], array['Registered MSME (Udyam)']::text[], array['Udyam certificate','Business financials']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'Ministry of MSME', 'https://msme.gov.in', 19900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', false, false, true, 52
