select 'gst-registration', c.id, 'service', 'GST Registration Guidance', 'जीएसटी पंजीकरण मार्गदर्शन', 'Understand if you need GST registration and how to apply.', 'क्या आपको जीएसटी पंजीकरण चाहिए और कैसे आवेदन करें।', 'GST registration is done on the GST portal. Whether it is mandatory depends on turnover thresholds and type of supply.', array['Legal compliance','Input tax credit']::text[], array['Businesses meeting GST registration criteria','Voluntary registration also allowed']::text[], array['PAN','Aadhaar','Business address proof','Bank details','Photographs']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'GST portal', 'https://www.gst.gov.in', 29900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', false, false, true, 53
