select 'startup-india', c.id, 'scheme', 'Startup India Recognition & Schemes', 'स्टार्टअप इंडिया मान्यता और योजनाएँ', 'DPIIT startup recognition and related support schemes.', 'डीपीआईआईटी स्टार्टअप मान्यता और संबंधित योजनाएँ।', 'Eligible startups can apply for DPIIT recognition on the Startup India portal, which can unlock certain benefits and scheme access.', array['DPIIT recognition','Access to seed fund and other schemes (subject to criteria)']::text[], array['Entity type, age and turnover criteria as per DPIIT notification','Working towards innovation']::text[], array['Certificate of incorporation/registration','Brief about the business','Directors'' details']::text[], array['Check eligibility on the official portal.','Keep the required documents ready.','Fill and submit the application on the official portal.','Note your application/acknowledgement number to track status.']::text[], '[{"label":"Application window","date":null,"note":"Check the official portal for current dates."}]'::jsonb, '[{"q":"Is Sabkaam a government website?","a":"No. Sabkaam is a private assistance platform. We are not affiliated with any government department. Official applications are made on the official portal linked on this page."},{"q":"Does paying for assistance guarantee approval?","a":"No. Approval is decided only by the relevant government department, bank or authority. Our fee covers guidance and application support only."}]'::jsonb, 'Startup India', 'https://www.startupindia.gov.in', 49900, array['Eligibility check against the published criteria','Personalised list of documents you need','Help filling the online form on the official portal','Review of your details before submission','Status follow-up guidance after submission']::text[], 'demo', false, false, true, 54
