insert into public.faqs (question, answer, question_hi, answer_hi, sort_order) select 'Is Sabkaam a government website?', 'No. Sabkaam is a private assistance platform and is not affiliated with any government department. We link to official portals for every service.', 'क्या सबकाम सरकारी वेबसाइट है?', 'नहीं। सबकाम एक निजी सहायता प्लेटफ़ॉर्म है और किसी सरकारी विभाग से संबद्ध नहीं है। हम हर सेवा के लिए आधिकारिक पोर्टल का लिंक देते हैं।', 0 where not exists (select 1 from public.faqs where question = 'Is Sabkaam a government website?');
insert into public.faqs (question, answer, question_hi, answer_hi, sort_order) select 'Is browsing free?', 'Yes. Searching and reading about any scheme or service is completely free. You only pay if you choose paid application assistance.', 'क्या जानकारी देखना मुफ़्त है?', 'हाँ। किसी भी योजना या सेवा को खोजना और पढ़ना पूरी तरह मुफ़्त है। आप केवल तभी भुगतान करते हैं जब आप सशुल्क सहायता चुनते हैं।', 1 where not exists (select 1 from public.faqs where question = 'Is browsing free?');
insert into public.faqs (question, answer, question_hi, answer_hi, sort_order) select 'Do you guarantee approval?', 'No. Approval is always decided by the government department, bank or authority. We help you apply correctly and completely.', 'क्या आप स्वीकृति की गारंटी देते हैं?', 'नहीं। स्वीकृति हमेशा सरकारी विभाग, बैंक या संस्था तय करती है। हम सही और पूरा आवेदन करने में मदद करते हैं।', 2 where not exists (select 1 from public.faqs where question = 'Do you guarantee approval?');
insert into public.faqs (question, answer, question_hi, answer_hi, sort_order) select 'Are government fees included in your fee?', 'No. Our fee is only for our assistance. Any official fee is paid by you directly on the official portal.', 'क्या सरकारी शुल्क आपके शुल्क में शामिल है?', 'नहीं। हमारा शुल्क केवल हमारी सहायता के लिए है। कोई भी सरकारी शुल्क आप सीधे आधिकारिक पोर्टल पर देते हैं।', 3 where not exists (select 1 from public.faqs where question = 'Are government fees included in your fee?');
insert into public.faqs (question, answer, question_hi, answer_hi, sort_order) select 'How are my documents protected?', 'Documents are stored in private, access-controlled storage and are only visible to you and the staff handling your request. We only ask for documents needed for your chosen service.', 'मेरे दस्तावेज़ कैसे सुरक्षित हैं?', 'दस्तावेज़ निजी, नियंत्रित स्टोरेज में रखे जाते हैं और केवल आपको और आपके अनुरोध पर काम करने वाले स्टाफ़ को दिखते हैं।', 4 where not exists (select 1 from public.faqs where question = 'How are my documents protected?');
insert into public.faqs (question, answer, question_hi, answer_hi, sort_order) select 'Can I get a refund?', 'Refunds follow our Refund Policy — for example, if we are unable to proceed with your request before work starts.', 'क्या मुझे रिफंड मिल सकता है?', 'रिफंड हमारी रिफंड नीति के अनुसार होते हैं — उदाहरण के लिए, यदि काम शुरू होने से पहले हम आपके अनुरोध पर आगे नहीं बढ़ पाते।', 5 where not exists (select 1 from public.faqs where question = 'Can I get a refund?');

insert into public.site_content (key, value_en, value_hi) values ('announcement', '', '') on conflict (key) do nothing;
insert into public.site_content (key, value_en, value_hi) values ('hero_description', '', '') on conflict (key) do nothing;

